#!/usr/bin/env node
/**
 * API contract → frontend.
 *
 *   npm run gen:api     regenerate src/core/api/contract.generated.js from ../openapi/openapi.json
 *   npm run check:api   fail when (a) the generated file is stale, or (b) any source file
 *                       calls an operation the backend does not expose (FE-05: no more
 *                       calls to endpoints that do not exist).
 *
 * Frontend code never hard-codes URLs: it calls api.call('<operationId>', …).
 */
import { readFileSync, writeFileSync, readdirSync, statSync } from 'node:fs';
import { join, relative } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = fileURLToPath(new URL('..', import.meta.url));
const specPath = join(root, '..', 'openapi', 'openapi.json');
const outPath = join(root, 'src', 'core', 'api', 'contract.generated.js');
const check = process.argv.includes('--check');

const spec = JSON.parse(readFileSync(specPath, 'utf8'));
const operations = {};
for (const [path, methods] of Object.entries(spec.paths)) {
  for (const [method, op] of Object.entries(methods)) {
    operations[op.operationId] = {
      method: method.toUpperCase(),
      path,
      auth: op['x-auth'] ?? 'user',
      profile: Boolean(op['x-profile']),
      idempotent: (op.parameters ?? []).some((p) => p.in === 'header' && p.name === 'Idempotency-Key'),
      errors: op['x-error-codes'] ?? [],
    };
  }
}
const sorted = Object.fromEntries(Object.entries(operations).sort(([a], [b]) => a.localeCompare(b)));
const source =
  '// AUTO-GENERATED by scripts/gen-api.mjs from openapi/openapi.json — do not edit.\n' +
  `// API ${spec.info.title} ${spec.info.version}\n` +
  `export const API_VERSION = ${JSON.stringify(spec.info.version)};\n` +
  `export const OPERATIONS = Object.freeze(${JSON.stringify(sorted, null, 2)});\n`;

function* sourceFiles(dir) {
  for (const name of readdirSync(dir)) {
    const full = join(dir, name);
    if (statSync(full).isDirectory()) yield* sourceFiles(full);
    else if (/\.(jsx?|mjs)$/.test(name) && !name.endsWith('.generated.js')) yield full;
  }
}

if (!check) {
  writeFileSync(outPath, source);
  console.warn(`wrote ${relative(root, outPath)} (${Object.keys(sorted).length} operations)`);
  process.exit(0);
}

let failed = false;
let current = '';
try { current = readFileSync(outPath, 'utf8'); } catch { /* missing */ }
if (current !== source) {
  console.error('✘ src/core/api/contract.generated.js is stale — run `npm run gen:api`');
  failed = true;
}
const used = /api\.(?:call|url|operation)\(\s*['"]([a-z0-9_]+)['"]/g;
for (const file of sourceFiles(join(root, 'src'))) {
  const text = readFileSync(file, 'utf8');
  for (const match of text.matchAll(used)) {
    if (!sorted[match[1]]) {
      console.error(`✘ ${relative(root, file)} calls unknown operation '${match[1]}'`);
      failed = true;
    }
  }
}
if (failed) process.exit(1);
console.warn(`✔ API contract in sync (${Object.keys(sorted).length} operations)`);
